// Extrai o texto da saída do agente e decide se a conversa deve ir para humano.
const agente = $('Agente Gemini (Ferramentas)').first().json || {};
let texto = agente.output || '';
if (!texto && agente.message) {
  const conteudo = agente.message.content;
  texto = typeof conteudo === 'string' ? conteudo : (Array.isArray(conteudo) ? conteudo.map(p => p.text || '').join('') : '');
}
if (!texto) texto = agente.text || '';
const norma = $('Normalizar Mensagem').first().json || {};
const regexPedido = /atendente|falar com (um|uma|algu[ée]m)|pessoa|humano/i;
let handoff = regexPedido.test(texto);
let handoffReason = handoff ? 'Pedido de atendente humano' : null;
if (!texto) {
  handoff = true;
  handoffReason = 'Falha interna do atendimento automático';
}
let responseText = texto;
if (!responseText) {
  responseText = 'Desculpe, não consegui processar sua mensagem agora. Vou transferir você para um atendente.';
}
return [{ json: { wa_id: norma.wa_id, responseText, handoff, handoffReason } }];

// Rama sem transferência (handoff=false): consolida a resposta no formato §2.2.
const deteccao = $('Detectar Pedido de Humano e Erro').first().json || {};
const norma = $('Normalizar Mensagem').first().json || {};
const texto = deteccao.responseText || 'Oi! Como posso ajudar você hoje?';
return [{ json: { messages: [{ to: deteccao.wa_id || norma.wa_id, type: 'text', text: texto }], human_handoff: false } }];

// Rama humana (handoff=true): mensagem de transferência com human_handoff=true (§2.2).
const deteccao = $('Detectar Pedido de Humano e Erro').first().json || {};
const norma = $('Normalizar Mensagem').first().json || {};
const fallbackPadrao = 'Oi! No momento estou com uma instabilidade e já estou transferindo você para um atendente humano. Por favor, aguarde alguns instantes que alguém vai te responder.';
const texto = deteccao.responseText || fallbackPadrao;
return [{ json: { messages: [{ to: deteccao.wa_id || norma.wa_id, type: 'text', text: texto }], human_handoff: true } }];
